1: import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
2: import type { RedactorService } from "../services/redactor.js";
3: 
4: export function registerHooks(pi: ExtensionAPI, redactor: RedactorService): void {
5:   // Update footer status on session start
6:   pi.on("session_start", async (_event, ctx) => {
7:     const status = redactor.isEnabled() ? "PII: On" : "PII: Off";
8:     ctx.ui.setStatus("pii-redact", status);
9:   });
10: 
11:   // Intercept user prompts before expansion or dispatch
12:   pi.on("input", async (event, ctx) => {
13:     if (!redactor.isEnabled() || !redactor.getConfig().maskUserInputs) {
14:       return undefined;
15:     }
16: 
17:     const result = await redactor.redact(event.text);
18:     if (result.hasRedactions) {
19:       if (redactor.getConfig().notifyOnRedact) {
20:         ctx.ui.notify(`Redacted ${result.count} sensitive item(s) from input`, "info");
21:       }
22:       return { action: "transform", text: result.text };
23:     }
24:     return undefined;
25:   });
26: 
27:   // Intercept tool results (e.g. read_file, bash output) before storing in session & sending to model
28:   pi.on("tool_result", async (event, ctx) => {
29:     if (!redactor.isEnabled() || !redactor.getConfig().maskToolResults) {
30:       return undefined;
31:     }
32: 
33:     if (!Array.isArray(event.content)) {
34:       return undefined;
35:     }
36: 
37:     let changed = false;
38:     let totalRedactions = 0;
39: 
40:     const sanitizedContent = await Promise.all(
41:       event.content.map(async (item) => {
42:         if (item && typeof item === "object" && "type" in item && item.type === "text" && typeof item.text === "string") {
43:           const result = await redactor.redact(item.text);
44:           if (result.hasRedactions) {
45:             changed = true;
46:             totalRedactions += result.count;
47:             return { ...item, text: result.text };
48:           }
49:         }
50:         return item;
51:       })
52:     );
53: 
54:     if (changed) {
55:       if (redactor.getConfig().notifyOnRedact) {
56:         ctx.ui.notify(`Redacted ${totalRedactions} item(s) from ${event.toolName} output`, "info");
57:       }
58:       return { content: sanitizedContent };
59:     }
60: 
61:     return undefined;
62:   });
63: 
64:   // Intercept messages in context before LLM requests
65:   pi.on("context", async (event, _ctx) => {
66:     if (!redactor.isEnabled() || !redactor.getConfig().maskContextMessages) {
67:       return undefined;
68:     }
69: 
70:     let modified = false;
71:     const sanitizedMessages = await Promise.all(
72:       event.messages.map(async (msg: any) => {
73:         if (typeof msg.content === "string") {
74:           const result = await redactor.redact(msg.content);
75:           if (result.hasRedactions) {
76:             modified = true;
77:             return { ...msg, content: result.text };
78:           }
79:         } else if (Array.isArray(msg.content)) {
80:           let blockModified = false;
81:           const newBlocks = await Promise.all(
82:             msg.content.map(async (block: any) => {
83:               if (block && block.type === "text" && typeof block.text === "string") {
84:                 const res = await redactor.redact(block.text);
85:                 if (res.hasRedactions) {
86:                   blockModified = true;
87:                   return { ...block, text: res.text };
88:                 }
89:               }
90:               return block;
91:             })
92:           );
93:           if (blockModified) {
94:             modified = true;
95:             return { ...msg, content: newBlocks };
96:           }
97:         }
98:         return msg;
99:       })
100:     );
101: 
102:     return modified ? { messages: sanitizedMessages } : undefined;
103:   });
104: }
