17: export class RedactorService {
18:   private rules: Map<string, PiiRule>;
19:   private config: RedactorConfig;
20:   private loadOptions?: LoadOptions;
21:   private instance: Redact | null = null;
22:   private initPromise: Promise<Redact> | null = null;
23:   private lastRestoreHelper?: (processed: string) => string;
24:   private lastRestoreMap: Map<string, string> = new Map();
25: 
26:   constructor(
27:     customRules: PiiRule[] = [],
28:     initialConfig?: Partial<RedactorConfig>,
29:     options?: RedactorServiceOptions | LoadOptions
30:   ) {
31:     this.rules = new Map();
32:     for (const rule of [...defaultRules, ...customRules]) {
33:       this.rules.set(rule.id, { ...rule });
34:     }
35: 
36:     this.config = {
37:       enabled: true,
38:       maskUserInputs: true,
39:       maskToolResults: true,
40:       maskContextMessages: true,
41:       notifyOnRedact: true,
42:       ...initialConfig,
43:     };
44: 
45:     if (options) {
46:       if ("redactInstance" in options || "loadOptions" in options) {
47:         const svcOpts = options as RedactorServiceOptions;
48:         this.loadOptions = svcOpts.loadOptions;
49:         if (svcOpts.redactInstance) {
50:           this.instance = svcOpts.redactInstance;
51:         }
52:       } else {
53:         this.loadOptions = options as LoadOptions;
54:       }
55:     }
56:   }
57: 
58:   /** Returns whether redaction is globally enabled. */
59:   public isEnabled(): boolean {
60:     return this.config.enabled;
61:   }
62: 
63:   /** Globally enable or disable redaction. */
64:   public setEnabled(enabled: boolean): void {
65:     this.config.enabled = enabled;
66:   }
67: 
68:   /** Returns read-only view of redactor configuration. */
69:   public getConfig(): Readonly<RedactorConfig> {
70:     return this.config;
71:   }
72: 
73:   /** Returns all registered rules (both native model labels and overlay rules). */
74:   public getRules(): PiiRule[] {
75:     return Array.from(this.rules.values());
76:   }
77: 
78:   /**
79:    * Toggles an individual rule by id (case, format, and alias insensitive).
80:    * Returns the new enabled state, or false if the rule was not found.
81:    */
82:   public toggleRule(ruleId: string, enabled?: boolean): boolean {
83:     const rule =
84:       this.rules.get(ruleId) ??
85:       findRuleByIdOrLabel(this.rules.values(), ruleId);
86: 
87:     if (!rule) return false;
88:     rule.enabled = enabled ?? !rule.enabled;
89:     return rule.enabled;
90:   }
91: 
92:   /**
93:    * Returns the initialized native Redact instance, loading it on demand if necessary.
94:    * Concurrent calls await the same initialization promise.
95:    */
96:   public async getRedactInstance(): Promise<Redact> {
97:     if (this.instance) {
98:       return this.instance;
99:     }
100:     if (!this.initPromise) {
101:       this.initPromise = (async () => {
102:         try {
103:           const loadOpts = {
104:             ...this.loadOptions,
105:             ...(this.config.modelDirectory && !this.loadOptions?.directory
106:               ? { directory: this.config.modelDirectory }
107:               : {}),
108:           };
109:           const inst = await NativeRedact.load(
110:             Object.keys(loadOpts).length > 0 ? loadOpts : undefined
111:           );
112:           this.instance = inst;
113:           return inst;
114:         } catch (error) {
115:           this.initPromise = null;
116:           throw error;
117:         }
118:       })();
119:     }
120:     return this.initPromise;
121:   }
122: 
123:   /** Eagerly initializes the native model. */
124:   public async init(): Promise<void> {
125:     await this.getRedactInstance();
126:   }
127: 
128:   /** Releases native engine resources. Safe to call multiple times. */
129:   public dispose(): void {
130:     if (this.instance) {
131:       this.instance.dispose();
132:       this.instance = null;
133:     }
134:     this.initPromise = null;
135:     this.lastRestoreHelper = undefined;
136:     this.lastRestoreMap.clear();
137:   }
138: 
139:   /**
140:    * Restores placeholders in text (e.g. an LLM response) back to their original sensitive values
141:    * using mappings from the most recent redaction. Handles both native redact-node placeholders
142:    * and secret overlay placeholders.
143:    */
144:   public restore(processed: string): string {
145:     if (!processed || typeof processed !== "string") {
146:       return processed ?? "";
147:     }
148:     let restored = processed;
149:     if (this.lastRestoreHelper) {
150:       restored = this.lastRestoreHelper(restored);
151:     }
152:     for (const [placeholder, original] of this.lastRestoreMap) {
153:       if (restored.includes(placeholder)) {
154:         restored = restored.replaceAll(placeholder, original);
155:       }
156:     }
157:     return restored;
158:   }
159: 
160:   /**
161:    * Asynchronously redacts sensitive data (PII and API secrets) from the input text.
162:    */
163:   public async redact(text: string): Promise<RedactionResult> {
164:     if (!this.config.enabled || !text || typeof text !== "string") {
165:       return {
166:         text: text ?? "",
167:         hasRedactions: false,
168:         count: 0,
169:         redactions: [],
170:         restore: (p: string) => p ?? "",
171:       };
172:     }
173: 
174:     let currentText = text;
175:     const allRedactions: RedactionDetail[] = [];
176: 
177:     // 1. Partition active rules into regex overlay rules vs native model labels
178:     const activeRegexRules: PiiRule[] = [];
179:     const activeNativeLabels: RedactLabel[] = [];
180: 
181:     for (const rule of this.rules.values()) {
182:       if (!rule.enabled) continue;
183: 
184:       if (rule.pattern) {
185:         activeRegexRules.push(rule);
186:       } else {
187:         const label =
188:           rule.nativeLabel ??
189:           RULE_ID_TO_LABEL[rule.id] ??
190:           (rule.id.toUpperCase().replace(/-/g, "_") as RedactLabel);
191:         if (label) {
192:           activeNativeLabels.push(label);
193:         }
194:       }
195:     }
196: 
197:     // 2. Phase 1: Apply regex overlay rules (API keys, IP addresses, custom secrets)
198:     const labelCounters: Record<string, number> = {};
199: 
200:     for (const rule of activeRegexRules) {
201:       const flags = rule.pattern!.flags.includes("g")
202:         ? rule.pattern!.flags
203:         : `${rule.pattern!.flags}g`;
204:       const regex = new RegExp(rule.pattern!.source, flags);
205: 
206:       currentText = currentText.replace(regex, (match) => {
207:         let masked: string;
208:         if (rule.mask) {
209:           masked = rule.mask(match);
210:         } else if (rule.nativeLabel) {
211:           labelCounters[rule.nativeLabel] = (labelCounters[rule.nativeLabel] || 0) + 1;
212:           masked = `[${rule.nativeLabel}_${labelCounters[rule.nativeLabel]}]`;
213:         } else {
214:           masked = `[REDACTED:${rule.id.toUpperCase()}]`;
215:         }
216: 
217:         allRedactions.push({
218:           category: rule.category,
219:           ruleId: rule.id,
220:           original: match,
221:           masked,
222:           placeholder: masked,
223:         });
224:         return masked;
225:       });
226:     }
227: 
228:     // 3. Phase 2: Apply native ML inference if any native labels are active
229:     // CRITICAL: If activeNativeLabels is empty, do NOT pass { labels: [] }, as
230:     // @desert-ant-labs/redact treats an empty array as ALL labels enabled.
231:     let nativeRestoreHelper: ((processed: string) => string) | undefined;
232: 
233:     if (activeNativeLabels.length > 0) {
234:       const redactInstance = await this.getRedactInstance();
235:       const options: { labels: Iterable<RedactLabel>; minimumConfidence?: number } = {
236:         labels: activeNativeLabels,
237:       };
238:       if (typeof this.config.minimumConfidence === "number") {
239:         options.minimumConfidence = this.config.minimumConfidence;
240:       }
241:       const nativeResult = await redactInstance.redaction(currentText, options);
242: 
243:       currentText = nativeResult.redactedText;
244:       nativeRestoreHelper = (p: string) => nativeResult.restore(p);
245: 
246:       for (const item of nativeResult.items) {
247:         // Revert known non-PII false positives
248:         if (FALSE_POSITIVE_ENTITIES.has(item.original.trim().toLowerCase())) {
249:           currentText = currentText.replaceAll(item.placeholder, item.original);
250:           continue;
251:         }
252: 
253:         const matchingRule = this.findRuleForNativeLabel(item.label);
254:         allRedactions.push({
255:           category: matchingRule?.category ?? this.mapNativeLabelToCategory(item.label),
256:           ruleId: matchingRule?.id ?? item.label.toLowerCase(),
257:           original: item.original,
258:           masked: item.placeholder,
259:           placeholder: item.placeholder,
260:           confidence: item.confidence,
261:           start: item.start,
262:           end: item.end,
263:         });
264: 
265:         // Ensure repeated identical occurrences of this detected PII entity are also sanitized
266:         if (item.original && item.original.length > 2 && currentText.includes(item.original)) {
267:           let count = 1;
268:           const matchNum = item.placeholder.match(/_(\d+)\]$/);
269:           if (matchNum) {
270:             count = parseInt(matchNum[1], 10);
271:           }
272:           while (currentText.includes(item.original)) {
273:             count++;
274:             const placeholder = item.placeholder.replace(/_\d+\]$/, `_${count}]`);
275:             currentText = currentText.replace(item.original, placeholder);
276:             allRedactions.push({
277:               category: matchingRule?.category ?? this.mapNativeLabelToCategory(item.label),
278:               ruleId: matchingRule?.id ?? item.label.toLowerCase(),
279:               original: item.original,
280:               masked: placeholder,
281:               placeholder,
282:               confidence: item.confidence,
283:             });
284:           }
285:         }
286:       }
287:     }
288: 
289:     // Build composite restoration map for this specific redaction result
290:     const currentRestoreMap = new Map<string, string>();
291:     for (const r of allRedactions) {
292:       if (r.masked && r.original) {
293:         currentRestoreMap.set(r.masked, r.original);
294:       }
295:       if (r.placeholder && r.original) {
296:         currentRestoreMap.set(r.placeholder, r.original);
297:       }
298:     }
299: 
300:     const restoreFn = (processed: string): string => {
301:       if (!processed || typeof processed !== "string") {
302:         return processed ?? "";
303:       }
304:       let restored = processed;
305:       // 1. Restore native engine placeholders via redact-node restore helper
306:       if (nativeRestoreHelper) {
307:         restored = nativeRestoreHelper(restored);
308:       }
309:       // 2. Restore overlay, repeated, and custom placeholders
310:       for (const [placeholder, original] of currentRestoreMap) {
311:         if (restored.includes(placeholder)) {
312:           restored = restored.replaceAll(placeholder, original);
313:         }
314:       }
315:       return restored;
316:     };
317: 
318:     // Store as service-level last restore state
319:     this.lastRestoreHelper = nativeRestoreHelper;
320:     this.lastRestoreMap = currentRestoreMap;
321: 
322:     return {
323:       text: currentText,
324:       hasRedactions: allRedactions.length > 0,
325:       count: allRedactions.length,
326:       redactions: allRedactions,
327:       restore: restoreFn,
328:     };
329:   }
330: 
331:   private findRuleForNativeLabel(label: string): PiiRule | undefined {
332:     return findRuleByIdOrLabel(this.rules.values(), label);
333:   }
334: 
335:   private mapNativeLabelToCategory(label: string): PiiCategory {
336:     const upper = label.toUpperCase();
337:     switch (upper) {
338:       case "EMAIL":
339:         return "email";
340:       case "PHONE":
341:         return "phone";
342:       case "IP_ADDRESS":
343:         return "ip";
344:       case "CREDIT_CARD":
345:         return "credit-card";
346:       default:
347:         return upper as PiiCategory;
348:     }
349:   }
350: }
